    comp=collections.defaultdict(list)
    for i,(r,c) in enumerate(ones):
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                rr,cc=r+dr,c+dc
                if 0<=rr<H and 0<=cc<W and I[rr][cc]==1:
                    comp[id(ones)].append((rr,cc))
    # simpler: flood connected components
    seen=set();groups=[]
    for (r,c) in ones:
        if (r,c) in seen:continue
        grp=[];st=[(r,c)];seen.add((r,c))
        while st:
            a,b=st.pop();grp.append((a,b))
            for da in(-1,0,1):
                for db in(-1,0,1):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and I[x][y]==1 and (x,y) not in seen:
                        seen.add((x,y));st.append((x,y))
        groups.append(grp)
    out=[row[:] for row in I]
    for grp in groups:
        rs=[p[0] for p in grp];cs=[p[1] for p in grp]
        r0,r1=min(rs)-1,max(rs)+1;c0,c1=min(cs)-1,max(cs)+1
        for r in range(r0,min(max(r1),H)):
