import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def solve(I):
    from collections import Counter
    H=len(I);W=len(I[0]);out=[row[:] for row in I]
    counts=Counter(x for row in I for x in row)
    v=min(counts,key=lambda x:counts[x])
    for r in range(H):
        for c in range(W):
            if I[r][c]==v:
                nbs=[(r+dr,c+dc) for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)) if 0<=r+dr<H and 0<=c+dc<W and I[r+dr][c+dc]==v]
                if nbs:
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=r+dr,c+dc
                            if 0<=rr<H and 0<=cc<W and out[rr][cc]!=v: out[rr][cc]=3
    return out
print('demo1:',solve(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print('demo2:',solve(G['Demo pair 2 input'])==G['Demo pair 2 output'])
out=solve(G['Test input'])
print(json.dumps(out))
